# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KEHF SURESİ: HZ. MUSA VE HIZIR KISSASI (قِصَّةُ مُوسَى وَالْعَبْدِ الصَّالِحِ)</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Kıssanın Ana Unsurları (Kehf, 60-82)</text>\n  <text x="42" y="96" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Yolculuk Amacı:</tspan> İlim öğrenme aşkı (طَلَبُ الْعِلْمِ)</text>\n  <text x="42" y="118" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Buluşma Yeri:</tspan> مَجْمَعَ الْبَحْرَيْنِ (İki denizin birleştiği yer)</text>\n  <text x="42" y="140" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Yol Arkadaşı:</tspan> الْفَتَى (Genç yardımcısı Yûşa b. Nûn)</text>\n  <text x="42" y="162" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Salih Kul (Hızır):</tspan> الْعَبْدُ الصَّالِحُ (Ledün ilmi verilen)</text>\n  <rect x="42" y="180" width="280" height="48" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="199" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">هَلْ أَتَّبِعُكَ عَلَى أَنْ تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا</text>\n  <text x="182" y="217" text-anchor="middle" font-size="10.5" fill="#1e3a8a">"Sana öğretilen rüşd (doğru bilgi)den bana öğretmen için..."</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Yolculuktaki Üç Olay ve Hikmeti</text>\n  <rect x="378" y="82" width="280" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="100" font-size="11" font-weight="bold" fill="#15803d">1. Geminin Kusurlu Kılınması (خَرْقُ السَّفِينَةِ)</text>\n  <text x="388" y="116" font-size="10.5" fill="#14532d">Zalim kralın yoksul denizcilerin gemisine el koymasını önlemek</text>\n  <rect x="378" y="134" width="280" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="152" font-size="11" font-weight="bold" fill="#15803d">2. Çocuk Olayı (الْغُلَامُ)</text>\n  <text x="388" y="168" font-size="10.5" fill="#14532d">Mümin anne-babayı azgınlık ve küfür fitnesinden korumak</text>\n  <rect x="378" y="186" width="280" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="204" font-size="11" font-weight="bold" fill="#15803d">3. Yıkık Duvarın Onarılması (إِقَامَةُ الْجِدَارِ)</text>\n  <text x="388" y="220" font-size="10.5" fill="#14532d">Salih bir babanın iki yetim çocuğuna ait hazineyi korumak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ULÜ\'L-AZM PEYGAMBERLER VE KISSALARDA GEÇEN FİİLLER</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Ulü\'l-Azm Peygamberler (أُولُو الْعَزْمِ مِنَ الرُّسُلِ)</text>\n  <text x="42" y="96" font-size="11.5" fill="#78350f">1. <tspan font-weight="bold">Hz. Nûh (نُوحٌ):</tspan> Tufan ve gemi (السَّفِينَةُ)</text>\n  <text x="42" y="118" font-size="11.5" fill="#78350f">2. <tspan font-weight="bold">Hz. İbrâhîm (إِبْرَاهِيمُ):</tspan> Tevhid mücadelesi (خَلِيلُ اللَّهِ)</text>\n  <text x="42" y="140" font-size="11.5" fill="#78350f">3. <tspan font-weight="bold">Hz. Mûsâ (مُوسَى):</tspan> Firavun\'a karşı mücadele (كَلِيمُ اللَّهِ)</text>\n  <text x="42" y="162" font-size="11.5" fill="#78350f">4. <tspan font-weight="bold">Hz. Îsâ (عِيسَى):</tspan> İncil ve mucizeler (رُوحُ اللَّهِ)</text>\n  <text x="42" y="184" font-size="11.5" fill="#78350f">5. <tspan font-weight="bold">Hz. Muhammed (مُحَمَّدٌ):</tspan> Son peygamber (خَاتَمُ النَّبِيِّينَ)</text>\n  <rect x="42" y="198" width="280" height="30" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Ahzâb 7 ve Şûrâ 13. ayetlerde birlikte anılırlar</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Kıssada Mücerred ve Mezîd Fiiller</text>\n  <rect x="378" y="84" width="280" height="68" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="388" y="102" font-size="11.5" font-weight="bold" fill="#7e22ce">Sülâsî Mücerred Fiiller (الْفِعْلُ الْمُجَرَّدُ):</text>\n  <text x="388" y="120" font-size="11" fill="#581c87">• قَالَ (dedi), وَجَدَ (buldu), رَكِبَ (bindi),</text>\n  <text x="388" y="138" font-size="11" fill="#581c87">• صَبَرَ (sabretti), سَأَلَ (sordu), خَرَقَ (deldi).</text>\n  <rect x="378" y="160" width="280" height="68" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="388" y="178" font-size="11.5" font-weight="bold" fill="#7e22ce">Mezîd Fiiller (الْفِعْلُ الْمَزِيدُ):</text>\n  <text x="388" y="196" font-size="11" fill="#581c87">• عَلَّمَ (öğretti - Tef\'îl), أَرَادَ (istedi - İf\'âl),</text>\n  <text x="388" y="214" font-size="11" fill="#581c87">• انْطَلَقَ (yola koyuldu - İnfial), اتَّبَعَ (tabi oldu - İftial).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ARAPÇADA İSTİFHAM (SORU) EDATLARI (أَدَوَاتُ الِاسْتِفْهَامِ)</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Soru Harfleri (حُرُوفُ الِاسْتِفْهَامِ)</text>\n  <text x="38" y="98" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">هَلْ / أَ (-mı, -mi?):</tspan></text>\n  <text x="46" y="116" font-size="10.5" fill="#1e3a8a">Olumlu sorularda cevabı</text>\n  <text x="46" y="132" font-size="10.5" fill="#1e3a8a"><tspan font-weight="bold">نَعَمْ</tspan> (evet) veya <tspan font-weight="bold">لَا</tspan> (hayır) olur.</text>\n  <rect x="38" y="148" width="178" height="76" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="46" y="168" font-size="10.5" font-weight="bold" fill="#1d4ed8">Olumsuz Soru (أَلَمْ / أَلَيْسَ):</text>\n  <text x="46" y="186" font-size="10" fill="#1e3a8a">"أَلَمْ أَقُلْ لَكَ" (Sana demedim mi?)</text>\n  <text x="46" y="202" font-size="10" fill="#1e3a8a">Olumlu cevap: <tspan font-weight="bold">بَلَى</tspan> (Evet, dedin)</text>\n  <text x="46" y="216" font-size="10" fill="#1e3a8a">Olumsuz cevap: <tspan font-weight="bold">نَعَمْ</tspan> (Hayır, demedin)</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Varlık ve Sebep Soruları</text>\n  <text x="260" y="98" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">مَنْ (Kim?):</tspan> Akıllı varlıklar</text>\n  <text x="260" y="122" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">مَا / مَاذَا (Ne?):</tspan> Akılsız</text>\n  <text x="268" y="138" font-size="10.5" fill="#14532d">varlıklar ve eylemler</text>\n  <text x="260" y="162" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">لِمَاذَا (Niçin / Neden?):</tspan></text>\n  <text x="268" y="178" font-size="10.5" fill="#14532d">Sebep ve gaye sorar</text>\n  <rect x="260" y="190" width="178" height="34" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="349" y="211" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">مَنْ هَذَا الرَّجُلُ؟ (Bu adam kimdir?)</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Zaman, Mekân ve Hal</text>\n  <text x="483" y="98" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">مَتَى (Ne zaman?):</tspan> Zaman</text>\n  <text x="483" y="122" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">أَيْنَ (Nerede / Nereye?):</tspan> Yer</text>\n  <text x="483" y="146" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">كَيْفَ (Nasıl?):</tspan> Hal / Durum</text>\n  <text x="483" y="170" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">كَمْ (Kaç?):</tspan> Sayı / Miktar</text>\n  <rect x="483" y="190" width="178" height="34" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="572" y="211" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">كَيْفَ تَصْبِرُ؟ (Nasıl sabredeceksin?)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
